// Extract URL data for processing
for (const item of $input.all()) {
  const urlData = item.json;

  // Prepare data for HTTP request
  item.json = {
    url_id: urlData.id,
    url: urlData.url,
    name: urlData.name,
    expected_response: urlData.expected_response,
    timeout: (urlData.timeout_seconds || 30) * 1000, // Convert to milliseconds
    failure_threshold: urlData.failure_threshold || 5,
    current_failures: urlData.current_failure_count || 0,
    priority: urlData.priority || 'normal',
    expected_chars: urlData.expected_response_chars || 200,
    http_method: urlData.http_method || 'GET',
    check_start_time: Date.now()
  };
}

return $input.all();

// Process HTTP response and determine health status
const items = [];

for (let i = 0; i < $input.all().length; i++) {
  const inputItem = $input.all()[i];
  const urlData = $('Prepare URL Data').all()[i].json;

  let status = 'error';
  let errorMessage = null;
  let responseTime = null;
  let httpStatusCode = null;
  let responsePreview = null;
  let responseHeaders = null;

  try {
    if (inputItem.json && !inputItem.error) {
      // Successful HTTP request
      const response = inputItem.json;
      httpStatusCode = response.statusCode || 0;
      responseTime = Date.now() - urlData.check_start_time;
      responseHeaders = response.headers || {};

      // Check if status code is 200
      if (httpStatusCode === 200) {
        status = 'up';

        // Get response preview
        const responseBody = response.body || '';
        responsePreview = responseBody.substring(0, urlData.expected_chars);

        // Check expected response if defined
        if (urlData.expected_response && urlData.expected_response.trim() !== '') {
          if (!responseBody.includes(urlData.expected_response)) {
            status = 'error';
            errorMessage = `Expected response '${urlData.expected_response}' not found`;
          }
        }
      } else {
        status = 'down';
        errorMessage = `HTTP ${httpStatusCode}`;
        responsePreview = (response.body || '').substring(0, urlData.expected_chars);
      }
    } else {
      // Error in request
      status = 'error';
      errorMessage = inputItem.error?.message || 'HTTP request failed';
      responseTime = Date.now() - urlData.check_start_time;
    }
  } catch (error) {
    status = 'error';
    errorMessage = error.message || 'Unknown processing error';
    responseTime = Date.now() - urlData.check_start_time;
  }

  // Calculate new failure count
  const newFailureCount = status === 'up' ? 0 : urlData.current_failures + 1;
  const shouldAlert = newFailureCount >= urlData.failure_threshold && status !== 'up' && urlData.current_failures < urlData.failure_threshold;

  items.push({
    json: {
      url_id: urlData.url_id,
      url: urlData.url,
      name: urlData.name,
      status: status,
      response_time_ms: responseTime,
      http_status_code: httpStatusCode,
      response_body_preview: responsePreview,
      response_headers: JSON.stringify(responseHeaders),
      error_message: errorMessage,
      current_failures: urlData.current_failures,
      new_failure_count: newFailureCount,
      failure_threshold: urlData.failure_threshold,
      priority: urlData.priority,
      should_alert: shouldAlert,
      checked_at: new Date().toISOString().slice(0, 19).replace('T', ' ')
    }
  });
}

return items;

// Prepare alert messages for different notification types with group context
const items = [];
const alertData = $('Update URL Status').first().json;

for (const recipient of $input.all()) {
  const recipientData = recipient.json;

  // Create alert message based on notification type
  let alertMessage = '';
  let subject = '';

  const recipientName = recipientData.member_name || recipientData.destination;
  const groupName = recipientData.group_name;

  if (recipientData.notification_type === 'email' || recipientData.notification_type === 'sms') {
    subject = `🚨 ${alertData.priority.toUpperCase()} Alert: ${alertData.name} [${groupName}]`;
    alertMessage = `Website Health Alert\n\n` +
                  `🚨 Status: ${alertData.status.toUpperCase()}\n` +
                  `📍 Site: ${alertData.name}\n` +
                  `🔗 URL: ${alertData.url}\n` +
                  `⚠️ Priority: ${alertData.priority.toUpperCase()}\n` +
                  `👥 Alert Group: ${groupName}\n` +
                  `👤 Recipient: ${recipientName}\n` +
                  `❌ Error: ${alertData.error_message || 'Unknown error'}\n` +
                  `📊 Response Time: ${alertData.response_time_ms || 'N/A'}ms\n` +
                  `🔄 Consecutive Failures: ${alertData.new_failure_count}/${alertData.failure_threshold}\n` +
                  `🕐 Time: ${new Date().toLocaleString()}\n\n` +
                  `Please check the website immediately.\n\n` +
                  `This alert was sent to the '${groupName}' alert group.`;
  } else if (recipientData.notification_type === 'telegram') {
    alertMessage = `🚨 *${alertData.priority.toUpperCase()} ALERT* [${groupName}]\n\n` +
                  `❌ *${alertData.name}* is DOWN\n` +
                  `🔗 ${alertData.url}\n\n` +
                  `Error: ${alertData.error_message || 'Unknown'}\n` +
                  `Failures: ${alertData.new_failure_count}/${alertData.failure_threshold}\n` +
                  `Time: ${new Date().toLocaleString()}\n` +
                  `Group: ${groupName}`;
  }

  items.push({
    json: {
      ...alertData,
      notification_type: recipientData.notification_type,
      destination: recipientData.destination,
      member_name: recipientName,
      group_name: groupName,
      group_id: recipientData.group_id,
      alert_message: alertMessage,
      alert_subject: subject
    }
  });
}

return items;
